-- 加载走 MDL3 的模组生命周期：文件末尾返回表里的 on_enable / on_update / on_disable。
-- 只认 update/shutdown 的旧宿主由末尾对 _G 的链式包装兜底，两者都挂上时每帧只跑一次。
if rawget(_G, "ARMOR_MULTI_PASSIVE_MDL3") then return end
rawset(_G, "ARMOR_MULTI_PASSIVE_MDL3", 1)

-- 版本号由构建脚本按 version.txt 覆盖；这里的字面量只在直接加载 src 时生效。
local MOD_VERSION = "1.8.1"

-- 判定跑在哪个加载器下：只读宿主暴露的全局，不做任何假设。
local function host_kind()
    if rawget(_G, "MDL3") ~= nil then return "MDL3" end
    if rawget(_G, "MDL") ~= nil then return "MDL" end
    if rawget(_G, "ModBindingsMenu") ~= nil then return "BML" end
    if rawget(_G, "CowboyBingusModLoader") ~= nil then return "BML" end
    return "standalone"
end

