local murmur = (function()
-- MurmurHash64A (HD2 LDLD content hash) and padding-word solver for Lua 5.1.
-- 64-bit values are four 16-bit limbs, little endian. No bit library required.
local floor = math.floor
local B = 65536

local function from_hex(h)
    local t = {0, 0, 0, 0}
    local n = #h / 2
    for i = 1, n do
        local byte = tonumber(h:sub(#h - 2 * i + 1, #h - 2 * i + 2), 16)
        local idx = floor((i - 1) / 2) + 1
        if i % 2 == 1 then
            t[idx] = t[idx] + byte
        else
            t[idx] = t[idx] + byte * 256
        end
    end
    return t
end

local M = from_hex('c6a4a7935bd1e995')
local INVERSE = from_hex('5f7a0ea7e59b19bd')
local SEED = from_hex('deadbeefabad1dea')

-- 64 位异或：原来是逐位循环（每次 64 轮除模），全选时是最大热点之一。
-- 改成 4 位 nibble 查表，每个 16 位 limb 只要 4 次查表。
local XOR4 = {}
for x = 0, 15 do
    local row = {}
    for y = 0, 15 do
        local v, w, bit, out = x, y, 1, 0
        for _ = 1, 4 do
            if (v % 2) ~= (w % 2) then out = out + bit end
            v, w, bit = floor(v / 2), floor(w / 2), bit * 2
        end
        row[y] = out
    end
    XOR4[x] = row
end

local function xor_limb(x, y)
    local lo = XOR4[x % 16][y % 16] + XOR4[floor(x / 16) % 16][floor(y / 16) % 16] * 16
    local hi = XOR4[floor(x / 256) % 16][floor(y / 256) % 16]
        + XOR4[floor(x / 4096) % 16][floor(y / 4096) % 16] * 16
    return lo + hi * 256
end

local function uxor(a, b)
    return {xor_limb(a[1] or 0, b[1] or 0), xor_limb(a[2] or 0, b[2] or 0),
        xor_limb(a[3] or 0, b[3] or 0), xor_limb(a[4] or 0, b[4] or 0)}
end

local function umul(a, b)
    local c = {0, 0, 0, 0, 0, 0, 0, 0}
    for i = 1, 4 do
        for j = 1, 4 do
            c[i + j - 1] = c[i + j - 1] + (a[i] or 0) * (b[j] or 0)
        end
    end
    for i = 1, 7 do
        local carry = floor(c[i] / B)
        c[i] = c[i] % B
        c[i + 1] = c[i + 1] + carry
    end
    return {c[1], c[2], c[3], c[4]}
end

local function rshift47(a)
    local a3, a4 = a[3] or 0, a[4] or 0
    return {floor(a3 / 32768) + (a4 % 32768) * 2, floor(a4 / 32768), 0, 0}
end

local function unshift(a)
    return uxor(a, rshift47(a))
end

local function from_le_bytes(s, pos, count)
    local t = {0, 0, 0, 0}
    for i = 0, count - 1 do
        local byte = s:byte(pos + i)
        local limb = floor(i / 2) + 1
        if i % 2 == 0 then
            t[limb] = t[limb] + byte
        else
            t[limb] = t[limb] + byte * 256
        end
    end
    return t
end

local function to_le_bytes(a)
    local out = {}
    for i = 0, 7 do
        local limb = floor(i / 2) + 1
        local v = a[limb] or 0
        if i % 2 == 0 then
            out[i + 1] = string.char(v % 256)
        else
            out[i + 1] = string.char(floor(v / 256) % 256)
        end
    end
    return table.concat(out)
end

local function mix(v)
    v = umul(v, M)
    v = unshift(v)
    return umul(v, M)
end

local function length64(n)
    return {n % B, floor(n / B) % B, floor(n / (B * B)) % B, floor(n / (B * B * B)) % B}
end

local function murmur64(data)
    local len = #data
    local h = uxor(SEED, umul(length64(len), M))
    local full = floor(len / 8) * 8
    for offset = 0, full - 1, 8 do
        local k = mix(from_le_bytes(data, offset + 1, 8))
        h = umul(uxor(h, k), M)
    end
    if full < len then
        h = umul(uxor(h, from_le_bytes(data, full + 1, len - full)), M)
    end
    h = unshift(h)
    h = umul(h, M)
    return unshift(h)
end

-- Solve the aligned eight-byte word at zero-based word_offset so the final
-- MurmurHash64A equals wanted. All other bytes stay fixed.
local function padding_word_for_hash(data, word_offset, wanted)
    local len = #data
    local full = floor(len / 8) * 8
    local after = unshift(umul(unshift(wanted), INVERSE))
    if full < len then
        after = uxor(umul(after, INVERSE), from_le_bytes(data, full + 1, len - full))
    end
    for offset = full - 8, word_offset + 8, -8 do
        after = uxor(umul(after, INVERSE), mix(from_le_bytes(data, offset + 1, 8)))
    end
    local before = uxor(SEED, umul(length64(len), M))
    for offset = 0, word_offset - 8, 8 do
        before = umul(uxor(before, mix(from_le_bytes(data, offset + 1, 8))), M)
    end
    local value = uxor(before, umul(after, INVERSE))
    value = unshift(umul(value, INVERSE))
    value = umul(value, INVERSE)
    return to_le_bytes(value)
end

-- 末尾补词时的常数开销解法。布局（总长一定是 8 的倍数）：
--   原数据 .. 零填充 .. [a, b, 0,0,0,0,0,0] .. 8 字节修正词
-- 修正词是最后一个整块、之后没有块，所以「后缀」只是常量；
-- 修正词之前的前缀哈希也只算一次。每次尝试只改 a、b 两个字节。
-- 命中「修正词首字节 == 1」之后用 murmur64 复核（与逐次重算等价）。
local function solve_tail_word(data, wanted, want_first_byte)
    want_first_byte = want_first_byte or 1
    -- 调用方已经把尾部补齐到 8 的倍数、并留了 16 字节自由空间，
    -- 这里直接就地覆盖最后 16 字节，不能自己再补一次（否则长度错位、哈希对不上）。
    local total = #data
    local block = total - 16               -- 可变块的 0-based 偏移
    local head = data:sub(1, block)
    local before0 = uxor(SEED, umul(length64(total), M))
    for offset = 0, block - 8, 8 do
        before0 = umul(uxor(before0, mix(from_le_bytes(head, offset + 1, 8))), M)
    end
    -- 后缀：修正词之后没有块，所以就是目标哈希反推一步。
    local after_const = unshift(umul(unshift(wanted), INVERSE))
    for attempt = 0, 65535 do
        local a, b = attempt % 256, floor(attempt / 256)
        local chunk = string.char(a, b, 0, 0, 0, 0, 0, 0)
        local before = umul(uxor(before0, mix(from_le_bytes(chunk, 1, 8))), M)
        local value = uxor(before, umul(after_const, INVERSE))
        value = unshift(umul(value, INVERSE))
        value = umul(value, INVERSE)
        local word_bytes = to_le_bytes(value)
        if word_bytes:byte(1) == want_first_byte then
            local out = head .. chunk .. word_bytes
            if #out == total and to_le_bytes(murmur64(out)) == to_le_bytes(wanted) then
                return out
            end
        end
    end
    return nil
end

-- 天然头字位置上的修正词求解。
-- 与 padding_word_for_hash 的差别：把「修正词之后」的反推结果提前算一次，
-- 循环里只重走「修正词之前」的短前缀，于是每次尝试是常数开销。
-- 原来每次尝试都要把整个文件走一遍，全选时要几十秒。
local function solve_natural_word(data, word_offset, wanted, want_first_byte)
    want_first_byte = want_first_byte or 1
    local len = #data
    local full = floor(len / 8) * 8
    local after = unshift(umul(unshift(wanted), INVERSE))
    if full < len then
        after = uxor(umul(after, INVERSE), from_le_bytes(data, full + 1, len - full))
    end
    for offset = full - 8, word_offset + 8, -8 do
        after = uxor(umul(after, INVERSE), mix(from_le_bytes(data, offset + 1, 8)))
    end
    local after_term = umul(after, INVERSE)
    local base = uxor(SEED, umul(length64(len), M))
    for attempt = 0, 65535 do
        local a, b = attempt % 256, floor(attempt / 256)
        local probe = data:sub(1, 21) .. string.char(a, b) .. data:sub(24)
        local before = base
        for offset = 0, word_offset - 8, 8 do
            before = umul(uxor(before, mix(from_le_bytes(probe, offset + 1, 8))), M)
        end
        local value = uxor(before, after_term)
        value = unshift(umul(value, INVERSE))
        value = umul(value, INVERSE)
        local bytes = to_le_bytes(value)
        if bytes:byte(1) == want_first_byte then
            local out = probe:sub(1, word_offset) .. bytes .. probe:sub(word_offset + 9)
            if to_le_bytes(murmur64(out)) == to_le_bytes(wanted) then
                return out
            end
        end
    end
    return nil
end

return {
    murmur64 = murmur64,
    padding_word_for_hash = padding_word_for_hash,
    solve_tail_word = solve_tail_word,
    solve_natural_word = solve_natural_word,
    to_le_bytes = to_le_bytes,
    from_le_bytes = from_le_bytes,
    uxor = uxor,
    M = M,
    SEED = SEED,
    INVERSE = INVERSE,
}

end)()
