local merger = (function()
-- Merge extra passives into a pinned HD2 LDLD passive-bonus plaintext.
-- No FFI, no external tools; Lua 5.1 only.
local floor = math.floor

local function u32(s, pos)
    local a, b, c, d = s:byte(pos, pos + 3)
    return a + b * 256 + c * 65536 + d * 16777216
end

local function u64(s, pos)
    local lo = u32(s, pos)
    local hi = u32(s, pos + 4)
    return lo + hi * 4294967296
end

local function u64bytes(n)
    if n < 0 then return string.rep('\255', 8) end
    local out = {}
    for i = 1, 8 do
        out[i] = string.char(n % 256)
        n = floor(n / 256)
    end
    return table.concat(out)
end

local function parse_blocks(data)
    local count = u32(data, 1)
    local pos = 5
    local blocks = {}
    for i = 1, count do
        local header = data:sub(pos, pos + 23)
        if header:sub(1, 4) ~= 'LDLD' then error('bad LDLD header') end
        local size = u32(header, 13)
        local payload = data:sub(pos + 24, pos + 23 + size)
        if #payload ~= size then error('truncated payload') end
        blocks[i] = {header = header, payload = payload, offset = pos - 1}
        pos = pos + 24 + size
    end
    if pos - 1 ~= #data then error('trailing bytes') end
    return blocks
end

local function decode(blocks)
    local records = {}
    for i, b in ipairs(blocks) do
        local p = b.payload
        if u32(b.header, 9) ~= 0x63ce0feb or b.header:byte(17) ~= 1 or #p < 56 then
            error('unsupported passive record')
        end
        local id = u32(p, 1)
        local pm_off, pm_count = u64(p, 17), u64(p, 25)
        local sm_off, sm_count = u64(p, 33), u64(p, 41)
        local function rows(off, count, width)
            local t = {}
            if count == 0 then return t end
            if off < 56 or off + count * width > #p then error('bad array') end
            for j = 0, count - 1 do
                t[j + 1] = p:sub(off + j * width + 1, off + (j + 1) * width)
            end
            return t
        end
        records[i] = {
            block = b, id = id, pm = rows(pm_off, pm_count, 16),
            sm = rows(sm_off, sm_count, 12), name_id = u32(p, 5),
        }
    end
    return records
end

local function append_unique(existing, extra, key_size)
    local out = {}
    local seen = {}
    for _, row in ipairs(existing) do
        out[#out + 1] = row
        seen[row:sub(1, key_size)] = true
    end
    for _, row in ipairs(extra) do
        local key = row:sub(1, key_size)
        if not seen[key] then
            out[#out + 1] = row
            seen[key] = true
        end
    end
    return out
end

local function build(original, selected, keep_original)
    local blocks = parse_blocks(original)
    local records = decode(blocks)
    if #records ~= 33 then error('unexpected record count') end
    local by_id = {}
    for _, r in ipairs(records) do by_id[r.id] = r end
    local extras = {}
    for _, id in ipairs(selected) do
        if id ~= 0 then
            if not by_id[id] then error('unknown passive id ' .. tostring(id)) end
            extras[#extras + 1] = by_id[id]
        end
    end
    local out = {string.char(#records % 256, floor(#records / 256) % 256,
        floor(#records / 65536) % 256, floor(#records / 16777216) % 256)}
    for _, r in ipairs(records) do
        -- keep_original == false wipes the armor's own passive: pm/sm start empty, so the
        -- rewritten record carries no effect of its own and only what was selected remains.
        -- Record 0 is structural and always keeps its original data.
        local pm, sm
        if keep_original ~= false or r.id == 0 then
            pm, sm = r.pm, r.sm
        else
            pm, sm = {}, {}
        end
        if r.id ~= 0 then
            for _, extra in ipairs(extras) do
                -- Keep the effect, but hide its description from the armor UI.
                local hidden = {}
                for _, row in ipairs(extra.pm) do
                    hidden[#hidden + 1] = row:sub(1, 12) .. '\0\0\0\0'
                end
                pm = append_unique(pm, hidden, 12)
                sm = append_unique(sm, extra.sm, 12)
            end
        end
        local header = r.block.header
        local payload = r.block.payload
        if (#extras > 0 or keep_original == false) and r.id ~= 0 then
            local pm_off = #pm > 0 and 56 or -1
            local sm_off = #sm > 0 and (56 + #pm * 16) or -1
            local p = payload:sub(1, 16)
            p = p .. u64bytes(pm_off) .. u64bytes(#pm)
            p = p .. u64bytes(sm_off) .. u64bytes(#sm)
            p = p .. payload:sub(49, 56)
            for _, row in ipairs(pm) do p = p .. row end
            for _, row in ipairs(sm) do p = p .. row end
            header = header:sub(1, 12) .. string.char(#p % 256, floor(#p / 256) % 256,
                floor(#p / 65536) % 256, floor(#p / 16777216) % 256) .. header:sub(17)
            payload = p
        end
        out[#out + 1] = header .. payload
    end
    local data = table.concat(out)
    -- 找一个没被使用的对齐头字（Is64Bit + 七个保留字节）当修正词位置。
    -- 取第一个候选：每次尝试都要重走「修正词之前」的块，位置越靠前越省。
    local word
    for _, b in ipairs(parse_blocks(data)) do
        local w = b.offset + 16
        if w % 8 == 0 and w > 28 and data:byte(w + 1) == 1 and data:sub(22, 23) == '\0\0' then
            word = w
            break
        end
    end
    if not word then
        -- 没有天然可用头字（全选 32 项时必然如此：块尺寸变化后没有任何块的
        -- offset+16 落在 8 字节对齐处）。往最后一个 payload 尾部补
        -- 「零填充 + 2 字节可变尾 + 8 字节修正词」，长度补成 8 的倍数。
        -- 求解是常数开销的解析解，不再每次重算整个文件（原来要 49 秒）。
        local blocks2 = parse_blocks(data)
        local last = blocks2[#blocks2]
        local pad = (8 - (#data % 8)) % 8
        local newpayload = last.payload .. string.rep('\0', pad + 16)
        local header = last.header:sub(1, 12) .. string.char(#newpayload % 256,
            floor(#newpayload / 256) % 256, floor(#newpayload / 65536) % 256,
            floor(#newpayload / 16777216) % 256) .. last.header:sub(17)
        local body = data:sub(1, last.offset) .. header .. newpayload
        local solved = murmur.solve_tail_word(body, murmur.murmur64(original), 1)
        if not solved then error('hash correction failed') end
        return solved
    end
    if data:sub(22, 23) ~= '\0\0' then
        error('no usable correction word')
    end
    -- 天然头字这条路每次尝试都要重走「修正词之前」的块；头字落在文件后半段时
    -- 光这一步就要几秒（实测 N=20 的时候头字在 17320 处，2164 个块 × 256 次）。
    -- 前缀超过 24 个块就改走末尾补词：它把前缀只算一次，耗时与文件长度无关。
    if word <= 24 * 8 then
        local solved = murmur.solve_natural_word(data, word, murmur.murmur64(original), 1)
        if solved then return solved end
    end
    local blocks2 = parse_blocks(data)
    local last = blocks2[#blocks2]
    local pad = (8 - (#data % 8)) % 8
    local newpayload = last.payload .. string.rep('\0', pad + 16)
    local header = last.header:sub(1, 12) .. string.char(#newpayload % 256,
        floor(#newpayload / 256) % 256, floor(#newpayload / 65536) % 256,
        floor(#newpayload / 16777216) % 256) .. last.header:sub(17)
    local body = data:sub(1, last.offset) .. header .. newpayload
    local solved = murmur.solve_tail_word(body, murmur.murmur64(original), 1)
    if not solved then error('hash correction failed') end
    return solved
end

return {build = build, parse_blocks = parse_blocks, decode = decode, u32 = u32, u64 = u64}

end)()
