-- Fixed-ephemeral sealed box for the Armory Forge multi-passive resource.
local keystream = material.keystream
local epk = material.epk
local polykey = material.poly

local xorb = {}
for a = 0, 255 do
    local row = {}
    for b = 0, 255 do
        local x, y, bit, v = a, b, 1, 0
        for _ = 1, 8 do
            local xa, yb = x % 2, y % 2
            if xa ~= yb then v = v + bit end
