        error('plaintext too large for precomputed keystream')
    end
    local out = {}
    for i = 1, #plaintext do
        out[i] = string.char(xorb[plaintext:byte(i)][keystream:byte(32 + i)])
    end
    local cipher = table.concat(out)
    local mac = poly(cipher, polykey)
    return epk .. mac .. cipher
end

return {seal = seal, epk = epk}

end)()

-- 离线应用器入口：游戏进程持有 dl_bin 时，rename 与原地写都会被 Windows 拒绝。
-- 在游戏外加载本文件时置 _G.ARMORY_FORGE_OFFLINE=true，只取纯函数，不碰宿主、
-- 不初始化、不写日志。此处 return 位于 if 块末尾，不影响后续代码加载。
if rawget(_G, "ARMORY_FORGE_OFFLINE") then
    return {
        passives = PASSIVES,
        original_plaintext = ORIGINAL_PLAINTEXT,
        original_sealed = ORIGINAL_SEALED,
        max_len = material.max_len,
        build = merger.build,
        seal = sealer.seal,
        epk = sealer.epk,
    }
end

-- Armory Forge: multi extra passives, in-game menu. Generated prefix provides
-- PASSIVES, GLYPHS, ORIGINAL_PLAINTEXT, ORIGINAL_SEALED, merger and sealer.
local sr = stingray
local target = "data/game/generated_customization_passive_bonuses.dl_bin"
local backup = "ArmoryForge-Multi.original.dl_bin"
local applied_path = "ArmoryForge-Multi.applied.dl_bin"
local state_path = "ArmoryForge-Multi.state"
local pending_path = "ArmoryForge-Multi.pending"
local temp_path = "data/game/ArmoryForge-Multi.tmp"
local rollback_path = "data/game/ArmoryForge-Multi.rollback"
local log_path = "ArmoryForge-Multi.log"
local keep_path = "ArmoryForge-Multi.keep_original"
local chosen, cursor, queued, reason = {}, 1, nil, nil
-- 模组设置页（见文件末尾的 OPTIONS 段）：改动先攒着，下一帧合并成一次排队。
local options_stage_pending = false
-- 面板里改了选择，需要把新状态推回 MDL 的设置页。
local options_push_all = false
-- 启动时 dl_bin 里真正生效的那组被动（chosen 是玩家正在编辑的草稿，两者可能不同）。
local active_ids = {}
local frames, opened, gui, gui_world, highlight = 0, false, nil, nil, nil
local by_id = {}
for i, p in ipairs(PASSIVES) do by_id[p.id] = p end

-- 日志上限 512 KB；超了就在本次启动时轮转成 .log.old（只留一份旧的）。
local LOG_LIMIT = 512 * 1024
local log_rotated = false
local function log_rotate()
    if log_rotated then return end
    log_rotated = true
    local f = io.open(log_path, "rb")
    if not f then return end
    local size = f:seek("end")
    f:close()
    if size and size > LOG_LIMIT then
        pcall(os.remove, log_path .. ".old")
        pcall(os.rename, log_path, log_path .. ".old")
    end
end

-- 时间戳用本地时间（原来是 UTC，和系统时间差整小时数，读日志要自己换算）。
local function log(s)
    log_rotate()
    local f = io.open(log_path, "ab")
    if f then f:write(os.date("%Y-%m-%d %H:%M:%S "), s, "\n"); f:close() end
end

local function read(path)
    local f = io.open(path, "rb")
    if not f then return nil end
    local b = f:read("*a")
    f:close()
    return b
end

local function write(path, bytes)
    local f, why = io.open(path, "wb")
    if not f then return nil, tostring(why) end
    local ok, err = f:write(bytes)
    local closed, close_err = f:close()
    if not ok or not closed then return nil, tostring(err or close_err) end
    if read(path) ~= bytes then return nil, "write verification failed" end
    return true
end

local function copy(set)
    local t = {}
    for k, v in pairs(set) do t[k] = v end
    return t
end

local function ids_list(set)
    local t = {}
    for _, p in ipairs(PASSIVES) do if set[p.id] then t[#t + 1] = p.id end end
    table.sort(t)
    return t
end

local function parse_ids(bytes)
    if not bytes then return nil end
    local body = bytes:match("^AF2\n([0-9,]*)")
    if not body then return nil end
    local set = {}
    for n in body:gmatch("%d+") do set[tonumber(n)] = true end
    return set
end

local function write_state(ids)
    local parts = {}
    for _, id in ipairs(ids) do parts[#parts + 1] = tostring(id) end
    return write(state_path, "AF2\n" .. table.concat(parts, ",") .. "\n")
end

-- "1" (default) keeps the armor's own passive, "0" disables it.
local keep_original = true
local function load_keep()
    local raw = read(keep_path)
    if not raw then return true end
    return raw:sub(1, 1) ~= "0"
end
local function save_keep(value)
    keep_original = value
    write(keep_path, value and "1" or "0")
    log("KEEP ORIGINAL " .. tostring(value))
    options_push_all = true
end

local applied_bytes = read(applied_path)
-- 游戏每次更新都会重新生成原版文件：内容全变、长度不变。所以原版基准放在 stock 里，
-- 而不是写死的常量；更新后首次运行会自动认领新原版。
local stock = ORIGINAL_SEALED
local function known(bytes)
    if not bytes then return false end
    if bytes == stock then return true end
    return applied_bytes ~= nil and bytes == applied_bytes
end

local function recover()
    local saved = read(rollback_path)
    if not saved then return true end
    if not known(saved) then return nil, "unknown rollback file" end
    local live = read(target)
    if live == nil then
        local ok, why = os.rename(rollback_path, target)
        if not ok then return nil, tostring(why) end
        if read(target) ~= saved then return nil, "rollback verification failed" end
        log("RECOVERED interrupted transaction")
    elseif known(live) then
        local ok, why = os.remove(rollback_path)
        if not ok then return nil, tostring(why) end
    else
        return nil, "unknown live file beside rollback"
    end
    return true
end

local function apply(desired, ids)
    local ok, why = recover()
    if not ok then return nil, why end
    local before = read(target)
    if not known(before) then return nil, "unknown target; restore the original first" end
    local saved = read(backup)
    if saved and saved ~= stock then return nil, "unknown backup; refused overwrite" end
    if not saved then
        ok, why = write(backup, stock)
        if not ok then return nil, why end
    end
    if before ~= desired then
        local stale = read(temp_path)
        if stale and not known(stale) then return nil, "unknown temporary file" end
        ok, why = write(temp_path, desired)
        if not ok then return nil, why end
        if read(target) ~= before then return nil, "target changed during preparation" end
        local renamed, rename_error = os.rename(target, rollback_path)
        if renamed then
            ok, why = os.rename(temp_path, target)
            if not ok then
                local restored, restore_error = os.rename(rollback_path, target)
                if not restored then return nil, "rollback retained: " .. tostring(restore_error) end
                return nil, "commit refused; original restored: " .. tostring(why)
            end
            ok, why = os.remove(rollback_path)
            if not ok then log("applied; rollback cleanup pending: " .. tostring(why)) end
        else
            -- 游戏进程存活期间独占这个 dl_bin，改名与原地覆盖都会拿到 Permission denied
            -- （同目录新建文件却成功，所以是句柄锁不是 ACL）；失败时由游戏外的应用器接管。
            local wrote, write_error = write(target, desired)
            pcall(os.remove, temp_path)
            if not wrote then
                -- 原地写失败可能已经把目标截断：用备份写回去，不留半个文件。
                local fallback = saved or stock
                local restored = write(target, fallback)
                return nil, "rename blocked (" .. tostring(rename_error) .. "); in-place write failed: "
                    .. tostring(write_error) .. (restored and "; original restored" or "; ORIGINAL NOT RESTORED")
            end
            log("COMMIT in-place; rename said: " .. tostring(rename_error))
        end
        if read(target) ~= desired then return nil, "commit verification failed; backup retained" end
    end
    ok, why = write(applied_path, desired)
    if not ok then return nil, "applied; sidecar write failed: " .. tostring(why) end
    applied_bytes = desired
    write_state(ids)
    return true
end

local function stage()
    if reason then return nil, reason end
    local ids = ids_list(chosen)
    local body = "AF2\n" .. table.concat(ids, ",") .. "\n"
    local ok, why = write(pending_path, body)
    if not ok then return nil, why end
    queued = copy(chosen)
    log("QUEUED " .. body:gsub("\n", " "))
    return true
end

local function initialize()
    local ok, why = recover()
    if not ok then reason = why; log("DISABLED " .. why); return end
    -- 游戏更新后会整份重生成该文件，live 既不是当前基准也不是我们写过的文件。
    local live_now = read(target)
    local saved_now = read(backup)
    if live_now ~= nil and live_now ~= stock and
       not (applied_bytes and live_now == applied_bytes) then
        -- live 不是我们写的，就是游戏当前生成的原版：整份备份下来，还原时能完整还回去。
        -- 输出仍用内置的原版明文重建——live 用的是我们没有的密钥，解不出明文。
        -- 备份可能是：不存在（首次）、旧基准、上次认领过的新原版，或更早的历史原版。
        -- 只要 live 不是我们写的，它就是当前真正的原版，直接用 live 覆盖备份。
        if saved_now ~= live_now then
            if saved_now ~= nil then log("REPLACED stale backup " .. tostring(#saved_now) .. " bytes") end
            local adopted, awhy = write(backup, live_now)
            if not adopted then reason = tostring(awhy); log("DISABLED adopt: " .. tostring(awhy)); return end
        end
        log("ADOPTED new stock " .. tostring(#stock) .. " -> " .. tostring(#live_now) .. " bytes")
        stock = live_now
    elseif applied_bytes and live_now == applied_bytes and
           saved_now ~= nil and saved_now ~= stock then
        -- 上次已经认领过新原版：备份就是当前原版，直接认它。
        stock = saved_now
        log("RESTORED stock from backup")
    end
    local saved = read(backup)
    if saved == nil then
        ok, why = write(backup, stock)
        if not ok then reason = why; log("DISABLED backup: " .. why); return end
    elseif saved ~= stock then
        reason = "unknown backup"; log("DISABLED unknown backup"); return
    end
    local live = read(target)
    if live == stock then
        chosen = {}
        active_ids = {}
        cursor = 1
    elseif applied_bytes and live == applied_bytes then
        chosen = parse_ids(read(state_path)) or {}
        active_ids = copy(chosen)
        cursor = 1
    else
        reason = "unknown target; restore original first"
        chosen = {}
        cursor = 1
    end
    local pending = parse_ids(read(pending_path))
    if pending then chosen = pending; queued = copy(pending) end
    log(string.format("START v%s host=%s Lua=%s chosen=%d reason=%s",
        MOD_VERSION, host_kind(), tostring(_VERSION), #ids_list(chosen), tostring(reason)))
end

-- Retained GUI; colors are created in the drawing frame.
-- ===== 可配置按键 =====
-- 默认键沿用原来的设计：F6 开关 / F5 保存 / F9 原被动 / Home 清空 / F7 按键设置 /
-- 方向键移动 / 空格勾选。玩家可以在 MDL3 的「按键绑定」页改（走 ModBindingsMenu），
-- 也可以在面板里按 F7 打开本地「按键设置」页改（BML 下没有 ModBindingsMenu 时用这条）。
-- 只允许功能键：F1-F12、Home、End、Ins、Del、PgUp/PgDn、方括号、方向键。
-- 移动键与 Esc 故意不放行——前者会边走路边开菜单，后者会和菜单自己的开关冲突。
local keys_path = "ArmoryForge-Multi.keys"
local BINDS = {
    {id = "toggle", label = "开关",     default = "f6",    names = {"f6"}, slot = 1},
    {id = "save",   label = "保存",     default = "f5",    names = {"f5"}, slot = 2},
    {id = "bare",   label = "原被动",   default = "f9",    names = {"f9"}, slot = 3},
    {id = "clear",  label = "清空",   default = "home",  names = {"home"}, slot = 4},
    {id = "pick",   label = "勾选",  default = "space", names = {"space"}, slot = 5},
    {id = "config", label = "按键设置", default = "f7",    names = {"f7"}, slot = 6},
    -- 方向键另外保留老键位当"附加键"：PgUp/PgDn 与 [ ] 一直能用，不因改键失效。
    {id = "up",     label = "上移",        default = "up",
     names = {"up", "arrow up", "up arrow", "navigate up", "dpad up"},
     extra = {"page up", "["}},
    {id = "down",   label = "下移",        default = "down",
     names = {"down", "arrow down", "down arrow", "navigate down", "dpad down"},
     extra = {"page down", "]"}},
    {id = "left",   label = "左移",        default = "left",
     names = {"left", "arrow left", "left arrow", "navigate left", "dpad left"}},
    {id = "right",  label = "右移",        default = "right",
     names = {"right", "arrow right", "right arrow", "navigate right", "dpad right"}},
}
local bind_name = {}
for _, b in ipairs(BINDS) do bind_name[b.id] = b.default end

-- 可绑定的键：键名 -> 面板上显示的名字。写死这张表，等于给「只许功能键」当闸门。
local BINDABLE = {
    {"f1", "F1"}, {"f2", "F2"}, {"f3", "F3"}, {"f4", "F4"}, {"f5", "F5"},
    {"f6", "F6"}, {"f7", "F7"}, {"f8", "F8"}, {"f9", "F9"}, {"f10", "F10"},
    {"f11", "F11"}, {"f12", "F12"},
    {"home", "Home"}, {"end", "End"}, {"insert", "Ins"}, {"delete", "Del"},
    {"page up", "PgUp"}, {"page down", "PgDn"}, {"[", "["}, {"]", "]"},
    {"up", "Up"}, {"down", "Down"}, {"left", "Left"}, {"right", "Right"},
    -- 勾选默认就是空格，所以它也算合法键；但设置页里空格同时是「开始改键」，
    -- 因此 config_capture 会跳过它，避免按空格把自己绑成空格。
    {"space", "空格"},
}

local function bind_readable(name)
    if not name then return "?" end
    for _, pair in ipairs(BINDABLE) do
        if pair[1] == name then return pair[2] end
    end
    return name
end

-- 提示行里用的短名：方向键写成中文单字，其余直接用键名。
local BIND_SHORT = {up = "上", down = "下", left = "左", right = "右"}
local function bind_short(id)
    local short = BIND_SHORT[id]
    if short then return short end
    return bind_readable(bind_name[id])
end

-- 底栏提示按当前绑定生成，改键后跟着变。
local function bind_hint_passive()
    return "开关 " .. bind_short("toggle") .. "  移动 " .. bind_short("up") .. "/" .. bind_short("down")
        .. "/" .. bind_short("left") .. "/" .. bind_short("right") .. "  勾选 " .. bind_short("pick")
        .. "  保存 " .. bind_short("save") .. "  原被动 " .. bind_short("bare")
        .. "  清空 " .. bind_short("clear") .. "  设置 " .. bind_short("config")
end
local function bind_hint_config()
    return "开关 " .. bind_short("toggle") .. "  " .. bind_short("up") .. "/" .. bind_short("down")
        .. " 选择  " .. bind_short("pick") .. " 改键  " .. bind_short("clear") .. " 恢复默认  "
        .. bind_short("config") .. " 返回"
end

-- 配置文件：每行「动作=键名」。故意用纯文本，玩家可以直接改，坏行会被忽略。
local function load_bindings()
    local raw = read(keys_path)
    if not raw then return end
    for line in raw:gmatch("[^\r\n]+") do
        local id, name = line:match("^%s*([%w_]+)%s*=%s*([^%s]+)%s*$")
        if id and name and bind_name[id] ~= nil then bind_name[id] = name end
    end
end

local function save_bindings()
    local parts = {}
    for _, b in ipairs(BINDS) do parts[#parts + 1] = b.id .. "=" .. tostring(bind_name[b.id]) end
    local body = table.concat(parts, "\n") .. "\n"
    local ok, why = write(keys_path, body)
    log("KEYS saved " .. table.concat(parts, " ") .. (ok and "" or (" failed: " .. tostring(why))))
    return ok
end

-- 键名是否在「只许功能键」白名单里。MDL 的按键页什么都能录，我们只能在使用层守。
local function bindable_key(name)
    if type(name) ~= "string" then return false end
    local lower = name:lower()
    for _, pair in ipairs(BINDABLE) do
        if pair[1] == lower then return true end
    end
    return false
end

-- A 路：MDL3 的 Mod Bindings Menu。玩家的改键存在 MDL.cfg 的 bindings 里，
-- 我们只注册、只读 is_down。注册完把默认键「种」进 MDL，这样它的按键页上
-- 能看到当前绑的是哪个键，而不是一片空白；同时把录进来的非功能键改回默认，
-- 让限制在 MDL 的页面里也成立。
local bind_api, bind_api_tried = nil, false
local bind_host = nil
-- 把本地默认键「种」进 MDL 的绑定表：MDL 的按键页因此能看到当前键，
-- 录进来的非功能键也会被改回默认（限制只在生效层守得住，MDL 界面本身拦不住录入）。
local function bind_sync_defaults()
    local host = bind_host
    if type(host) ~= "table" or type(host.set) ~= "function" then return end
    local store = host.store
    if type(store) ~= "table" then return end
    local seeded, rejected = 0, 0
    for _, b in ipairs(BINDS) do
        if b.slot then
            local key = "armory_" .. b.id
            local record = store[key]
            if type(record) ~= "table" or record.button == nil then
                pcall(host.set, key, {device = "keyboard", button = b.default})
                seeded = seeded + 1
            elseif record.device ~= "keyboard" or not bindable_key(record.button) then
                pcall(host.set, key, {device = "keyboard", button = b.default})
                rejected = rejected + 1
                log("KEYS reject " .. b.id .. "=" .. tostring(record.device) .. " " .. tostring(record.button))
            end
        end
    end
    if seeded > 0 then log("KEYS seeded " .. seeded .. " default bindings into MDL") end
    if rejected > 0 then log("KEYS reset " .. rejected .. " non-function bindings in MDL") end
end

-- 每 30 帧复核一次：MDL 的按键页可以直接录任意键，我们只能在生效层兜底，
-- 把录进来的非功能键改回默认，并把被清空的项重新种上默认键。
local bind_poll_frame = 0
local function bind_poll()
    if not bind_api then return end
    bind_poll_frame = bind_poll_frame + 1
    if bind_poll_frame % 30 ~= 0 then return end
    bind_sync_defaults()
end

-- 本地页改键：同步写一份到 MDL，保证两处不打架。
local function bind_push(key, name)
    local host = bind_host
    if type(host) ~= "table" or type(host.set) ~= "function" then return end
    pcall(host.set, "armory_" .. key, {device = "keyboard", button = name})
end

-- 取 MDL 侧的按键状态：true / false / nil（nil = 没注册或读不到，用本地键）。
-- 非白名单的键一律当作没绑，等于不生效。
local function bind_state(action)
    local api = bind_api
    if not api or type(api.is_down) ~= "function" then return nil end
    local key = "armory_" .. action
    local host = bind_host
    local record = type(host) == "table" and type(host.store) == "table" and host.store[key] or nil
    if record ~= nil then
        -- 只认键盘功能键：鼠标的 left/right 名字和方向键重名，必须连设备一起看。
        if type(record) ~= "table" or record.device ~= "keyboard"
            or not bindable_key(record.button) then return false end
    elseif host == nil and type(api.binding) == "function" then
        -- BML 的 ModBindingsMenu 是门面（版本 4），不暴露 store，玩家改的键存在它自己的设置里，
        -- 这里用 binding(id) 读回规范化结果；空表 = 玩家清掉了绑定，交回本地默认键。
        local list = select(2, pcall(api.binding, key))
        if type(list) ~= "table" or type(list[1]) ~= "table" then return nil end
        if list[1][1] ~= "keyboard" or not bindable_key(list[1][2]) then return false end
    end
    local ok, down = pcall(api.is_down, key)
    if not ok then return nil end
    return down
end
local function mdl_bindings()
    if bind_api_tried then return bind_api end
    bind_api_tried = true
    local mdl = rawget(_G, "MDL")
    if type(mdl) == "table" and type(mdl.bindings) == "table" then bind_host = mdl.bindings end
    local api = rawget(_G, "ModBindingsMenu")
    if type(api) == "table" and type(api.register_binding) == "function" then
        bind_api = api
        for _, b in ipairs(BINDS) do
            if b.slot then
                -- default 必须一起交上去：BML 的 register_binding 用它播种玩家的键，
                -- 不给的话它记的是空键，is_down 永远返回 false（BML 下按开关键没反应）。
                local ok, why = pcall(api.register_binding, "armory_" .. b.id, b.label, b.slot,
                    {category = "军械工坊", default = b.default})
                if not ok then log("BIND register failed " .. b.id .. ": " .. tostring(why)) end
            end
        end
        log("BIND api ready version=" .. tostring(api.version))
        bind_sync_defaults()
    end
    return bind_api
end


-- 「按键设置」页的状态：cfg_page 决定画哪一页，cfg_cursor 是当前行，
-- cfg_waiting 表示正在等玩家按下一个新键。
local cfg_page, cfg_cursor, cfg_waiting = false, 1, false

local panel_x, panel_y, panel_w, panel_h, scale, screen_h
-- These only order elements *inside* this screen GUI. The game's own HUD and menus are
-- XAML, a separate render system that draws after sr.Gui, so no value here can put the
-- panel above them. Kept at the original values.
local LAYER_BG, LAYER_FG, LAYER_TEXT = 1000, 1001, 1002

-- ==== 原生字体（优先）====
-- 点阵字每个汉字要拼二三十个小矩形，边缘是块状、1080p 下更糊。
-- 这里照 Chef 沙箱的调用方式直接用引擎字体，任何一步不对就永久退回点阵字。
local font_ready, font_dead = false, false
local font_name, font_cap = nil, nil
local font_tries = 0
local FONT_MAT = "content/fonts/runtime_font"
local FONT_CANDIDATES = { "content/fonts/fallback", "content/fonts/fs_sinclair_medium_runtime", "9ad413a8fea59728" }
-- TEXT_PX 是一个汉字应该占多少像素高：列表行距 35，留一点缝就是 30。
-- GLYPH_H 是点阵字的行高，用来把原生文字的基线放到和点阵字一样的位置。
local TEXT_PX, GLYPH_H = 28, 32

-- 字体 id 不能留到下一帧：每帧要用就现生成一个。
local function font_arg(name)
    if type(name) ~= "string" then return nil end
    if not name:match("^%x+$") then return name end
    if type(sr.IdString64) ~= "table" or type(sr.IdString64.from_hex) ~= "function" then return nil end
    local ok, id = pcall(sr.IdString64.from_hex, name)
    if ok then return id end
    return nil
end

local function can_get(kind, value)
    local app = sr.Application
    if type(app) ~= "table" or type(app.can_get) ~= "function" then return false end
    local ok, result = pcall(app.can_get, kind, value)
    return ok and result == true
end

-- 在 size 号字下量一段字的宽度，量不到返回 nil。
local function measure_width(value, size)
    if type(sr.Gui.text_extents) ~= "function" then return nil end
    local fid = font_arg(font_name)
    if fid == nil then return nil end
    local ok, got = pcall(function()
        local lo, hi = sr.Gui.text_extents(gui, value, fid, size)
        if lo == nil or hi == nil then return nil end
        return (hi.x - lo.x) / (scale or 1)
    end)
    if ok and type(got) == "number" then return got end
    return nil
end

-- 在 100 号字下量一个汉字的高度。汉字是方块字，它的高度才代表实际占的大小；
-- 用大写字母 'H' 的 cap 高会小看汉字（cap 只有 88 而汉字接近满格），字号就会算大。
local function measure_cap()
    if type(sr.Gui.text_extents) ~= "function" then return nil end
    local fid = font_arg(font_name)
    if fid == nil then return nil end
    local ok, got = pcall(function()
        local lo, hi = sr.Gui.text_extents(gui, "中", fid, 100)
        if lo == nil or hi == nil then return nil end
        return hi.y - lo.y
    end)
    if ok and type(got) == "number" and got >= 10 and got <= 200 then return got end
    return nil
end

-- 崩溃守卫：上一次用引擎字体时把游戏带崩过，这次就直接用点阵字。
-- 做法是启用前先落一个标记文件，稳定跑满 180 帧再删；下次启动看到标记就说明崩过。
local FONT_MARKER = "ArmoryForge-Multi.font"

local function font_marked()
    local f = io.open(FONT_MARKER, "rb")
    if f then f:close() return true end
    return false
end

local function font_mark(on)
    if on then
        local f = io.open(FONT_MARKER, "wb")
        if f then f:write("1\n") f:close() end
    else
        pcall(os.remove, FONT_MARKER)
    end
end

local function setup_font()
    if font_dead then return false end
    if font_tries == 0 and font_marked() then
        font_dead = true
        log("FONT disabled: the game font crashed a previous launch, using the pixel font "
            .. "(delete " .. FONT_MARKER .. " to try again)")
        return false
    end
    font_ready = false
    font_tries = font_tries + 1
    local function give_up(why)
        -- 没真的用上引擎字体，标记要撤掉，否则下次启动会被误判成「崩过」。
        font_mark(false)
        if font_tries == 1 or font_tries % 300 == 0 then log("FONT unavailable: " .. why) end
        return false
    end
    if not gui then return false end
    if type(sr.Gui) ~= "table" or type(sr.Gui.text) ~= "function" then return give_up("no Gui.text") end
    -- 从这里开始就要碰引擎字体了：先落标记，真崩了下次启动直接点阵字。
    font_mark(true)
    if not can_get("material", FONT_MAT) then return give_up("no runtime_font material") end
    -- 挑一个游戏已加载的字体；汉字量不出宽度（没有中文字形）就跳过。
    for _, name in ipairs(FONT_CANDIDATES) do
        local fid = font_arg(name)
        if fid ~= nil and can_get("runtime_font", fid) then
            font_name, font_cap = name, nil
            local cap = measure_cap()
            local cjk = measure_width("中", 100)
            if cjk and cjk > 0 then
                -- 汉字是方块字，宽度就等于它的占格大小；不同机器上「高度」量出来
                -- 差别很大（88.5 与 115.4 都见过），宽度反而稳定，所以用宽度当基准。
                font_cap = cjk
                font_ready = true
                font_stable = 0
                log(string.format("FONT native ready: %s (metric %.1f, cap %.1f)", name, cjk, cap or 0))
                return true
            end
            font_name = nil
        end
    end
    return give_up("no font with CJK glyphs")
end

-- 目标行高 GLYPH_H 对应的引擎字号：Chef 的做法是 100 号字量出 cap 高，
-- 再按「想要的行高 / cap」反推（chef_bridge.lua 的 size_of）。
local function font_size(ratio)
    local base
    if font_cap and font_cap > 0 then base = 100 * TEXT_PX / font_cap else base = TEXT_PX end
    base = base * (ratio or 1)
    -- 兜底夹紧：量出来的度量再离谱，字号也落在 18..40 之间，免得糊成一团或小到看不见。
    if base < 18 then base = 18 end
    if base > 40 then base = 40 end
    return base
end

local font_stable = 0

local function native_text(value, x, top, color, ratio)
    if not font_ready then return false end
    font_stable = font_stable + 1
    if font_stable == 180 then font_mark(false) end
    local fid = font_arg(font_name)
    if fid == nil then
        font_ready, font_dead = false, true
        log("FONT disabled: font id lost")
        return false
    end
    local p = sr.Vector3(panel_x + x * scale, screen_h - panel_y - (top + GLYPH_H) * scale, LAYER_TEXT)
    local ok, id = pcall(sr.Gui.text, gui, value, fid, font_size(ratio) * scale, FONT_MAT, p, color)
    if not ok or id == nil then
        font_ready, font_dead = false, true
        log("FONT disabled: " .. tostring(id))
        return false
    end
    return true
end

-- 宽度：优先问引擎要真实排版宽度；问不到（字体没就绪）就返回 nil 让调用方走点阵字。
local function native_width(value, ratio)
    if not font_ready then return nil end
    return measure_width(value, font_size(ratio) * scale)
end
local function rect(x, top, w, h, color, layer)
    return sr.Gui.rect(gui, sr.Vector3(panel_x + x * scale, screen_h - panel_y - (top + h) * scale, layer), sr.Vector2(w * scale, h * scale), color)
end
local function text(value, x, top, color)
    if native_text(value, x, top, color) then return end
    local cursor_x, p = x, 1
    while p <= #value do
        local b = value:byte(p)
        local n = b < 128 and 1 or (b < 224 and 2 or (b < 240 and 3 or 4))
        local glyph = GLYPHS[value:sub(p, p + n - 1)] or GLYPHS["?"]
        for _, box in ipairs(glyph.boxes) do
            rect(cursor_x + box[1], top + box[2], box[3], box[4], color, LAYER_TEXT)
        end
        cursor_x = cursor_x + glyph.advance
        p = p + n
    end
end
local white, muted, gold, gold_bright, background, selection_color, accent_dim
local panel_fill, row_fill, line_color, dim
-- 两列纵向排布：每列 16 行，一屏看完 32 项。
local LIST_X, LIST_TOP, LIST_ROW, LIST_COL = 30, 108, 35, 380
local LIST_PAGES = math.ceil(#PASSIVES / 2)
local function selection_position(index)
    local col = math.floor((index - 1) / LIST_PAGES)
    local row = (index - 1) % LIST_PAGES
    return LIST_X + col * LIST_COL, LIST_TOP + row * LIST_ROW
end
local function close_menu()
    opened = false
    if gui and sr.Application.main_world() == gui_world then pcall(sr.World.destroy_gui, gui_world, gui) end
    gui, gui_world, highlight = nil, nil, nil
end
local function count_chosen()
    local n = 0
    for _ in pairs(chosen) do n = n + 1 end
    return n
end
local function text_width(value)
    local native = native_width(value)
    if native then return native end
    local total, p = 0, 1
    while p <= #value do
        local b = value:byte(p)
        local n = b < 128 and 1 or (b < 224 and 2 or (b < 240 and 3 or 4))
        local glyph = GLYPHS[value:sub(p, p + n - 1)] or GLYPHS["?"]
        total = total + glyph.advance
        p = p + n
    end
    return total
end

local function wrap_text(value, limit)
    local lines, cur, p = {}, "", 1
    while p <= #value do
        local b = value:byte(p)
        local n = b < 128 and 1 or (b < 224 and 2 or (b < 240 and 3 or 4))
        local ch = value:sub(p, p + n - 1)
        local glyph = GLYPHS[ch] or GLYPHS["?"]
        if cur ~= "" and text_width(cur) + glyph.advance > limit then
            lines[#lines + 1] = cur
            cur = ch
        else
            cur = cur .. ch
        end
        p = p + n
    end
    if cur ~= "" then lines[#lines + 1] = cur end
    return lines
end

local function text_right(value, right, top, color)
    text(value, right - text_width(value), top, color)
end

-- 列表与详情正文字形纵向压到 0.82：原字形是按 43px 行距设计的，
-- 我们要在 16 行里塞进两列，行距只有 35，不压就会上下贴在一起。
local COMPACT = 0.82
local function text_compact(value, x, top, color)
    if native_text(value, x, top, color) then return end
    local cursor_x, p = x, 1
    while p <= #value do
        local b = value:byte(p)
        local n = b < 128 and 1 or (b < 224 and 2 or (b < 240 and 3 or 4))
        local glyph = GLYPHS[value:sub(p, p + n - 1)] or GLYPHS["?"]
        for _, box in ipairs(glyph.boxes) do
            local hh = math.max(1, math.floor(box[4] * COMPACT + 0.5))
            rect(cursor_x + box[1], top + math.floor(box[2] * COMPACT), box[3], hh, color, LAYER_TEXT)
        end
        cursor_x = cursor_x + glyph.advance
        p = p + n
    end
end

-- 名字太长时整体横向压缩到给定宽度，保证不会压到右列或详情栏。
local function text_fit(value, x, top, color, max_width)
    local w = text_width(value)
    if font_ready then
        local ratio = 1
        if w and w > max_width and w > 0 then ratio = max_width / w end
        if native_text(value, x, top, color, ratio) then return end
    end
    if w <= max_width then
        text_compact(value, x, top, color)
        return
    end
    local k = max_width / w
    local cursor_x, p = x, 1
    while p <= #value do
        local b = value:byte(p)
        local n = b < 128 and 1 or (b < 224 and 2 or (b < 240 and 3 or 4))
        local glyph = GLYPHS[value:sub(p, p + n - 1)] or GLYPHS["?"]
        for _, box in ipairs(glyph.boxes) do
            local ww = math.max(1, math.floor(box[3] * k + 0.5))
            local hh = math.max(1, math.floor(box[4] * COMPACT + 0.5))
            local xx = cursor_x + math.floor(box[1] * k + 0.5)
            rect(xx, top + math.floor(box[2] * COMPACT), ww, hh, color, LAYER_TEXT)
        end
        cursor_x = cursor_x + math.floor(glyph.advance * k + 0.5)
        p = p + n
    end
end

-- 日志节流：只在第一次绘制和已选数量变化时记一行
local drawn_once, drawn_chosen = false, nil
local function draw_menu(world)
    if sr.Application.main_world() ~= world then error("world identity is not stable") end
    -- 绝地潜兵 2 界面配色：近黑底 + 暖白字 + 警戒黄，危险红只留在错误提示。
    white = sr.Color(255, 232, 226, 212)
    muted = sr.Color(255, 148, 150, 143)
    gold = sr.Color(255, 255, 199, 44)
    gold_bright = sr.Color(255, 255, 226, 120)
    background = sr.Color(247, 8, 10, 12)
    selection_color = sr.Color(200, 40, 30, 16)
    accent_dim = sr.Color(150, 112, 40, 255)
    panel_fill = sr.Color(255, 14, 16, 19)
    row_fill = sr.Color(255, 38, 32, 18)
    line_color = sr.Color(255, 52, 46, 32)
    dim = sr.Color(255, 96, 92, 78)
    gui_world = world
    -- Chef 与 SquadPing 建文字 GUI 都带 'scale', 1, 1；不带的 GUI 画字会让引擎崩。
    gui = sr.World.create_screen_gui(world, "scale", 1, 1) or sr.World.create_screen_gui(world)
    local w, h = sr.Application.back_buffer_size()
    screen_h = h
    scale = math.min(w / 1920, h / 1080, 1.15)
    panel_w, panel_h = 1200, 960
    panel_x, panel_y = (w - panel_w * scale) / 2, (h - panel_h * scale) / 2
    -- 面板每帧整屏重建，字体只在还没就绪时隔一会儿重试。
    if not font_ready and not font_dead and (frames % 60 == 0 or font_tries == 0) then setup_font() end
    rect(0, 0, panel_w, panel_h, background, LAYER_BG)
    rect(0, 0, panel_w, 2, gold, LAYER_FG)
    rect(0, panel_h - 2, panel_w, 2, accent_dim, LAYER_FG)
    rect(0, 0, 4, panel_h, gold, LAYER_FG)
    local n = count_chosen()
    -- 字号随字体变（点阵字 32px、引擎字体按像素折算），所以标题各段的位置要按实测宽度排，
    -- 不能写死坐标，否则换了字体就会挤在一起。
    text("军械工坊", 30, 14, gold)
    local title_x = 30 + text_width("军械工坊") + 8
    text("v" .. MOD_VERSION, title_x, 20, muted)
    text_right("已选 " .. n .. " / " .. #PASSIVES, 1164, 14, gold_bright)
    text_right(keep_original and "原被动 保留" or "原被动 已关", 1164, 55, keep_original and muted or gold)
    rect(30, 70, 1140, 1, accent_dim, LAYER_FG)
    if cfg_page then
        text("按键设置", 30, 84, gold)
        text("只允许功能键：F1-F12 / Home / End / PgUp / PgDn / [ ] / 方向键", 30, 128, muted)
        -- 「开始改键」用的是勾选键，可能被玩家改掉，这里也跟着走。
        text("按 " .. bind_short("pick") .. " 后，再按一次新按键即可绑定；再按 "
            .. bind_short("pick") .. " 取消。", 30, 164, dim)
        for i, b in ipairs(BINDS) do
            local y = 214 + (i - 1) * 42
            local shown = bind_readable(bind_name[b.id])
            local label
            if cfg_waiting and i == cfg_cursor then
                label = b.label .. "    =  按下新按键"
            else
                label = b.label .. "    =  " .. shown
            end
            if i == cfg_cursor then
                rect(24, y - 3, 520, 38, row_fill, LAYER_FG)
                rect(24, y - 3, 4, 38, gold, LAYER_FG)
                text(">", 10, y, gold)
            end
            text(label, 44, y, (i == cfg_cursor) and gold or white)
        end
        -- 底部的键名必须跟着玩家的绑定走，不能写死。
        text(bind_short("clear") .. " 恢复默认    " .. bind_short("config") .. " 返回",
            44, 214 + #BINDS * 42 + 16, dim)
        rect(24, 214 + #BINDS * 42 - 6, 520, 1, line_color, LAYER_FG)
    else
        text("01 - 21", LIST_X, 78, dim)
        text("31 - 42", LIST_X + LIST_COL, 78, dim)
        rect(LIST_X + LIST_COL - 24, 92, 2, 736, line_color, LAYER_FG)
        rect(LIST_X + LIST_COL - 27, 84, 8, 4, accent_dim, LAYER_FG)
        for i, p in ipairs(PASSIVES) do
            local x, y = selection_position(i)
            local is_sel = (i == cursor)
            local on = chosen[p.id]
            if is_sel then
                rect(x - 12, y - 2, LIST_COL - 28, LIST_ROW - 2, row_fill, LAYER_FG)
                rect(x - 12, y - 2, 4, LIST_ROW - 2, gold, LAYER_FG)
            end
            local row_color = on and gold_bright or (is_sel and gold or white)
            text_compact(on and "[x]" or "[ ]", x, y, row_color)
            text_compact(string.format("%02d", p.id), x + 50, y, is_sel and gold or muted)
            text_fit(p.zh, x + 98, y, row_color, LIST_COL - 122)
        end
        -- 右侧详情栏
        local p = PASSIVES[cursor]
        rect(766, 86, 404, 752, panel_fill, LAYER_FG)
        rect(766, 86, 2, 752, line_color, LAYER_FG)
        text("当前选中", 788, 96, muted)
        text_fit(p.zh, 788, 136, gold, 358)
        text("编号 " .. string.format("%02d", p.id), 788, 178, dim)
        -- 状态与编号同一行：详情栏下半段要全留给底部清单。
        -- 勾选只是草稿，要保存并由游戏外的应用器写进 dl_bin，所以这里必须区分三态。
        local active = active_ids[p.id] and true or false
        local state_text, state_color
        if chosen[p.id] and active then
            state_text, state_color = "已生效", gold_bright
        elseif chosen[p.id] then
            state_text, state_color = "待应用", gold
        elseif active then
            state_text, state_color = "待取消", muted
        else
            state_text, state_color = "未勾选", dim
        end
        text(state_text, 788 + text_width("编号 00") + 24, 178, state_color)
        rect(788, 214, 358, 1, line_color, LAYER_FG)
        text("效果", 788, 222, muted)
        local y = 258
        for _, line in ipairs(PASSIVE_DESC[p.id] or {}) do
            for _, wrapped in ipairs(wrap_text(line, 358)) do
                rect(790, y + 10, 8, 8, gold, LAYER_FG)
                text_compact(wrapped, 802, y, white)
                y = y + 35
            end
        end
        y = y + 20
        -- 底部清单分三块：已生效 / 待应用 / 待取消。
        -- 草稿不能叫「生效中」——按下保存只是排队，真正的写盘要在游戏外完成。
        local area_w = 350
        local bottom = 832
        -- 行高必须大于字号：原生字体 28px、点阵字 32px，行距小于字号会上下叠在一起。
        local row_h, gap = 32, 22
        local active_names, pend_new, pend_gone = {}, {}, {}
        for _, q in ipairs(PASSIVES) do
            if active_ids[q.id] then active_names[#active_names + 1] = q end
            if chosen[q.id] and not active_ids[q.id] then pend_new[#pend_new + 1] = q end
            if not chosen[q.id] and active_ids[q.id] then pend_gone[#pend_gone + 1] = q end
        end
        local active_n = #active_names
        -- 待应用 / 待取消 最多各占两行（标题 + 一行名字），多出来的收成「等 N 项」。
        -- 否则一次勾十几个，这块会把整个详情栏顶满，和上面的「已生效」压在一起。
        local function tail_lines(group)
            local names, line, count = {}, "", 0
            for _, q in ipairs(group) do
                local piece = (#names > 0 and "/" or "") .. q.zh
                if line ~= "" and (text_width(line .. piece) > area_w - 24) then break end
                line = line .. piece
                names[#names + 1] = q.zh
                count = count + 1
            end
            if count < #group then
                line = line .. " 等 " .. #group .. " 项"
            end
            return line
        end
        local new_line, gone_line = tail_lines(pend_new), tail_lines(pend_gone)
        local tail_h = 0
        if #pend_new > 0 then tail_h = tail_h + 34 + row_h + 8 end
        if #pend_gone > 0 then tail_h = tail_h + 34 + row_h end
        local head = math.max(390, math.min(y, 430))
        rect(788, head, 358, 1, line_color, LAYER_FG)
        text("已生效 " .. active_n .. " 项", 788, head + 12, muted)
        local list_y = head + 50
        local list_limit = bottom - tail_h - (tail_h > 0 and 18 or 0)
        if active_n > 0 then
            local cx, cy, shown = 788, list_y, 0
            for _, q in ipairs(active_names) do
                local name_w = math.min(text_width(q.zh), area_w)
                if cx > 788 and cx + 15 + name_w - 788 > area_w then
                    cx, cy = 788, cy + row_h
                end
                if cy + row_h > list_limit then break end
                rect(cx + 2, cy + 11, 7, 7, gold_bright, LAYER_FG)
                text_fit(q.zh, cx + 15, cy, gold_bright, area_w - (cx - 788))
                cx = cx + 15 + name_w + gap
                shown = shown + 1
            end
            if shown < active_n then
                -- 放不下时在标题里标注，不能另起一行：那行会和下面的待重启块贴在一起。
                text("已生效 " .. active_n .. " 项 / 显示 " .. shown, 788, head + 12, muted)
            end
        else
            text("未选被动", 788, list_y, dim)
        end
        local pend_y = bottom - tail_h
        if #pend_new > 0 then
            text("待应用 " .. #pend_new .. " 项", 788, pend_y, gold)
            text_fit(new_line, 802, pend_y + 34, gold, area_w - 24)
            pend_y = pend_y + 34 + row_h + 8
        end
        if #pend_gone > 0 then
            text("待取消 " .. #pend_gone .. " 项", 788, pend_y, muted)
            text_fit(gone_line, 802, pend_y + 34, muted, area_w - 24)
        end
    end
    rect(30, 860, 1140, 1, accent_dim, LAYER_FG)
    if cfg_page then
        local note = cfg_waiting and "等待新按键" or "改完立刻生效，并写入 ArmoryForge-Multi.keys。"
        text(note, 30, 874, cfg_waiting and gold_bright or muted)
    else
        -- 保存键可能被玩家改成 F4 之类，这里跟着走。
        local status = reason or (queued and ("已保存 " .. n .. " 项｜退出游戏后运行一次应用器")
            or ("勾选后按 " .. bind_short("save") .. " 保存，退出游戏后运行应用器写入。"))
        text(status, 30, 874, reason and gold_bright or muted)
    end
    local hint = cfg_page and bind_hint_config() or bind_hint_passive()
    local hy = 914
    for _, line in ipairs(wrap_text(hint, 1156)) do
        text(line, 30, hy, white)
        hy = hy + 26
    end
    -- 每次重绘都写日志会刷出上千行噪音：只记第一次绘制与选择数量变化。
    if not drawn_once or n ~= drawn_chosen then
        drawn_once, drawn_chosen = true, n
        log("MENU drawn chosen=" .. n .. " scale=" .. tostring(scale))
    end
end
local function redraw_now()
    -- close_menu + reopened would leave one frame with no GUI at all, which reads as a
    -- flicker. Rebuilding right here keeps the panel continuous.
    local world = sr.Application.main_world()
    close_menu()
    opened = true
    if world then
        local ok, why = pcall(draw_menu, world)
        if not ok then log("REDRAW ERROR " .. tostring(why)) end
    end
end
local function choose(index)
    cursor = ((index - 1) % #PASSIVES) + 1
    redraw_now()
end
local function choose_by(columns)
    -- 左右跨列：两列布局，跨一列等于挪「每列行数」个位置。
    -- 越界停在原地不回绕，免得按一下跑到面板另一头。
    local target = cursor + columns * LIST_PAGES
    if target < 1 or target > #PASSIVES then return end
    cursor = target
    redraw_now()
end
local function toggle(index)
    local p = PASSIVES[index]
    if chosen[p.id] then chosen[p.id] = nil else chosen[p.id] = true end
    log("TOGGLE " .. p.id .. "=" .. tostring(chosen[p.id] == true))
    options_push_all = true
    redraw_now()
end
local keys
local draw_failed = false

local function bind_button(name)
    local ok, id = pcall(sr.Keyboard.button_id, name)
    if ok and id ~= nil then return id end
end

local function rebuild_keys()
    keys = { extra = {} }
    for _, b in ipairs(BINDS) do
        local name = bind_name[b.id]
        local id = nil
        if name then
            id = bind_button(name)
            if id == nil then
                for _, alt in ipairs(b.names) do
                    id = bind_button(alt)
                    if id ~= nil then break end
                end
            end
        end
        keys[b.id] = id
        -- 附加键（老键位）始终有效：改绑不会让 PgUp/PgDn、[ ] 突然失效。
        if b.extra then
            local list = {}
            for _, alt in ipairs(b.extra) do
                local eid = bind_button(alt)
                if eid ~= nil then list[#list + 1] = eid end
            end
            keys.extra[b.id] = list
        end
    end
    keys.pick = keys.pick or bind_button("space")
end

local function pressed_extra(action)
    local extra = keys.extra and keys.extra[action]
    if extra then
        for _, eid in ipairs(extra) do
            if sr.Keyboard.pressed(eid) == true then return true end
        end
    end
    return false
end

local function pressed(action)
    local id = keys[action]
    if id ~= nil and sr.Keyboard.pressed(id) == true then return true end
    return pressed_extra(action)
end

-- MDL3/BML 一旦有绑定，就以它为准：本地默认键不再额外生效
-- （否则改绑之后老键还留着，等于没改）。方向键没注册上去，仍走本地。
local function act(action)
    local state = bind_state(action)
    if state ~= nil then
        if state == true then return true end
        return pressed_extra(action)
    end
    return pressed(action)
end

-- 开关类动作取「上升沿」：MDL/BML 的 is_down 表示按住，按住期间每一帧都是真，
-- 直接拿它切换面板会让面板每帧翻转（画面闪烁、按几下才停到打开状态）。
-- 这里记下上一次的状态，只在「上一帧没按、这一帧按下」时算一次动作。
local edge_state = {}     -- 上一帧是否按下
local edge_last = {}      -- 上次触发时的帧号
local edge_armed = {}     -- 是否可以再触发一次（只有开关键用）
local edge_release = {}   -- 连续松手的帧数
-- 开关键触发一次之后，必须先松开够这么多帧才准许下一次触发。
-- 实测（朋友机器）日志里同一个键会以 13~31 帧的间隔连续给出「真/假」脉冲，
-- 只靠冷却会让面板一路翻下去（刚开就又关了）。人手连点一次也快不过 0.3 秒，
-- 所以这个门槛只影响「被宿主当成连发」的情况，不影响正常操作。
local EDGE_RELEASE = 40
-- 额外冷却：约 0.75 秒，拦手抖与宿主重复触发。
local EDGE_COOLDOWN = 45
local function act_once(action, cool, release)
    local down = act(action)
    local prev = edge_state[action]
    edge_state[action] = down
    if down ~= true then
        edge_release[action] = (edge_release[action] or 0) + 1
        if release and edge_release[action] >= release then edge_armed[action] = true end
        return false
    end
    edge_release[action] = 0
    if prev == true then return false end
    if release then
        if edge_armed[action] == false then return false end
        edge_armed[action] = false
    end
    -- 只有开关键吃冷却：它是最容易被按住/手抖连点误触的动作。
    -- 其它动作（勾选、保存、设置页）保持零冷却，连按就是连按。
    cool = cool or 0
    local last = edge_last[action]
    if cool > 0 and last and frames - last < cool then return false end
    edge_last[action] = frames
    return true
end

-- 方向键：按下先动一格，按住约 0.2 秒后开始重复，重复间隔约 0.1 秒。
-- 既不会一按就飞出去，也不会按着不动毫无反应。
local EDGE_DELAY, EDGE_RATE = 12, 6
local edge_hold = {}
local function act_repeat(action)
    local down = act(action)
    local held = edge_hold[action]
    if down ~= true then
        edge_hold[action] = nil
        return false
    end
    if held == nil then
        edge_hold[action] = 0
        return true
    end
    held = held + 1
    edge_hold[action] = held
    if held <= EDGE_DELAY then return false end
    return (held - EDGE_DELAY) % EDGE_RATE == 0
end

-- B 路：本地设置页。cfg_waiting 为真时，下一个按下的可绑定键直接改绑。
local function enter_config()
    cfg_page, cfg_cursor, cfg_waiting = true, 1, false
    opened = true
    redraw_now()
    log("KEYS page opened")
end

local function leave_config()
    cfg_page, cfg_waiting = false, false
    redraw_now()
    log("KEYS page closed")
end

local function config_step(delta)
    cfg_cursor = ((cfg_cursor - 1 + delta) % #BINDS) + 1
    redraw_now()
end

local function config_capture()
    -- 只认功能键：BINDABLE 之外的键一律忽略，Esc/移动键因此不会被绑上。
    for _, pair in ipairs(BINDABLE) do
        local id = pair[1] ~= "space" and bind_button(pair[1])
        if id and sr.Keyboard.pressed(id) then
            local target = BINDS[cfg_cursor]
            bind_name[target.id] = pair[1]
            cfg_waiting = false
            save_bindings()
            bind_push(target.id, pair[1])
            rebuild_keys()
            redraw_now()
            log("KEYS bind " .. target.id .. "=" .. pair[1])
            return true
        end
    end
    return false
end

local function config_reset()
    for _, b in ipairs(BINDS) do bind_name[b.id] = b.default end
    save_bindings()
    for _, b in ipairs(BINDS) do bind_push(b.id, b.default) end
    rebuild_keys()
    redraw_now()
    log("KEYS reset to default")
end

local function update_menu()
    frames = frames + 1
    if not keys then
        load_bindings()
        rebuild_keys()
        mdl_bindings()
    end
    bind_poll()
    -- 开关键：设置页打开时先关设置页，不回落到关面板。
    if act_once("toggle", EDGE_COOLDOWN, EDGE_RELEASE) then
        if cfg_page then
            leave_config()
        else
            if opened then close_menu() else opened = true end
            -- 带上帧号：同一帧里反复翻转 = 按住被当成连续触发；间隔很多帧 = 用户连点。
            log("TOGGLE opened=" .. tostring(opened) .. " f=" .. tostring(frames))
        end
    end
    -- 面板没开时一律不响应（F7 只在 mod 界面里生效，避免和 MDL 的按键页抢键）。
    if not opened then return end
    if cfg_page and cfg_waiting then config_capture(); return end
    if act_once("config") then
        if cfg_page then leave_config() else enter_config() end
        return
    end
    local world = sr.Application.main_world()
    if not world then return end
    if gui and world ~= gui_world then gui, gui_world, highlight = nil, nil, nil end
    if not gui then
        local ok_draw, why_draw = pcall(draw_menu, world)
        if not ok_draw and not draw_failed then
            draw_failed = true
            log("DRAW ERROR " .. tostring(why_draw))
        end
    end
    if cfg_page then
        if pressed("up") then config_step(-1); return end
        if pressed("down") then config_step(1); return end
        if pressed("pick") then cfg_waiting = true; redraw_now(); return end
        if pressed("clear") then config_reset(); return end
        return
    end
    -- 上/下/左/右：方向键优先，再回退到 PgUp/PgDn。
    -- 方向键要「按住连续滚动」的手感，但不能每帧都滚（60 帧/秒会飞出去）。
    if act_repeat("left") then choose_by(-1) end
    if act_repeat("right") then choose_by(1) end
    if act_repeat("up") then choose(cursor - 1) end
    if act_repeat("down") then choose(cursor + 1) end
    if act_once("pick", 0) then toggle(cursor) end
    if act_once("bare") then
        save_keep(not keep_original)
        redraw_now()
    end
    if act_once("clear") then chosen = {}; redraw_now(); log("CLEAR") end
    if act_once("save") then
        local ok, why = stage()
        reason = not ok and why or nil
        if not ok then log("QUEUE ERROR " .. tostring(why)) end
        close_menu(); opened = true
    end
end
local failed = false
local function safe_update()
    if failed then return end
    local ok, why = pcall(update_menu)
    if not ok then failed = true; pcall(close_menu); log("UI ERROR " .. tostring(why)) end
end
local function finish(tag)
    tag = tag or "exit"
    local bytes = read(pending_path)
    local ids = parse_ids(bytes)
    if not ids then
        if tag ~= "boot" then log("EXIT no pending selection") end
        return
    end
    if tag == "boot" then
        -- 启动时 pending 已经是文件里的状态：只清标记，不重写。
        local same = true
        for id in pairs(ids) do if not active_ids[id] then same = false; break end end
        if same then
            for id in pairs(active_ids) do if not ids[id] then same = false; break end end
        end
        if same then
            pcall(os.remove, pending_path)
            log("BOOT pending already applied")
            return
        end
    end
    local list = {}
    for _, p in ipairs(PASSIVES) do if ids[p.id] then list[#list + 1] = p.id end end
    table.sort(list)
    local desired
    if #list == 0 and keep_original then
        -- 什么都没选、且保留护甲自带的被动：还原成当前游戏真正的那份原版。
        -- 用 stock（可能已被游戏重新生成过），不能再用内置旧文件，
        -- 否则会把游戏新增的被动数据一并抹掉。
        desired = stock
    else
        local ok, plain = pcall(merger.build, ORIGINAL_PLAINTEXT, list, keep_original)
        if not ok then log("MERGE ERROR " .. tostring(plain)); return end
        local ok2, boxed = pcall(sealer.seal, plain)
        if not ok2 then log("SEAL ERROR " .. tostring(boxed)); return end
        desired = boxed
    end
    local ok, why = apply(desired, list)
    if not ok then
        log((tag == "boot" and "BOOT APPLY ERROR " or "APPLY ERROR ") .. tostring(why)
            .. " | 游戏进程持有 dl_bin，退出游戏后运行 tools/apply_pending.py")
        return
    end
    active_ids = ids
    if read(pending_path) == bytes then os.remove(pending_path) end
    log((tag == "boot" and "APPLIED AT BOOT ids=" or "APPLIED ids=")
        .. table.concat(list, ",") .. " bytes=" .. #desired)
end
-- ---------------------------------------------------------------------------
-- 启动与驱动：
--   * 不覆盖 _G.init / _G.render（覆盖会让游戏主循环与渲染停摆）；
--   * 只认 update/shutdown 的宿主（如 BML）靠末尾对 _G 的链式包装：先调原有的
--     update（游戏自己的，或别的 mod 的包装），再跑本 mod 菜单，谁也不会吞掉谁；
--   * shutdown 先写盘，再调用原有 shutdown。
local function noop() end
if sr.Application.build() ~= "release" then pcall(require, "debug") end
local jit_library = rawget(_G, "jit")
if jit_library then jit_library.off() end
keep_original = load_keep()
local started, start_error = pcall(initialize)
if not started then reason = tostring(start_error); log("INIT ERROR " .. reason) end
-- 游戏进程从启动到退出一直独占地持有 dl_bin，退出时那次写必然失败；启动阶段调用
-- finish("boot") 只是让「排队内容与已生效状态一致」时能清掉残留的 pending 标记。
if started and reason == nil then pcall(finish, "boot") end

-- ===== 模组设置页（ModOptionsMenu）=====
-- MDL3 与 BML 都会先于本 mod 设好全局 ModOptionsMenu（api 1 / version 3）。
-- 有它的时候，把 32 个被动和「保留护甲自带被动」各注册成一个开关，
-- 玩家可以直接在游戏自己的模组设置页里点选。这里与 F6 面板共用同一份草稿
-- chosen：改动只排队，由游戏外的应用器写入 dl_bin——游戏运行时这个文件被独占，
-- 模组自己无论何时都写不进去（与面板上按一下保存等价）。
-- 没有这个 API（例如裸跑）时整段不生效，F6 面板照旧能用。
local options_api = rawget(_G, "ModOptionsMenu")
local options_ready = type(options_api) == "table" and options_api.api == 1
    and type(options_api.register_option) == "function"
    and type(options_api.set) == "function"

-- 排队：与面板上的保存同一个动作，只是不关面板。
local function options_stage()
    local ok, why = stage()
    if not ok then log("OPTIONS stage failed: " .. tostring(why)) end
end

-- 把当前草稿推给设置页，让两处显示一致。
local function options_sync()
    if not options_ready then return end
    for _, p in ipairs(PASSIVES) do
        pcall(options_api.set, "armory_passive_" .. p.id, chosen[p.id] == true)
    end
    pcall(options_api.set, "armory_keep_original", keep_original == true)
end

-- 玩家在设置页里改了一下：同步进草稿，然后排队（合并到下一帧）。
local function options_apply(id, value)
    local num = tonumber(tostring(id):match("^armory_passive_(%d+)$"))
    if num ~= nil then
        if value == true then chosen[num] = true else chosen[num] = nil end
        log("OPTIONS passive " .. num .. "=" .. tostring(value == true))
    elseif id == "armory_keep_original" then
        save_keep(value == true)
    else
        return
    end
    options_stage_pending = true
    if opened then redraw_now() end
end

local function options_register()
    if not options_ready then return end
    local made, failed = 0, 0
    for _, p in ipairs(PASSIVES) do
        local id = "armory_passive_" .. p.id
        local desc = PASSIVE_DESC[p.id]
        local called, done, why = pcall(options_api.register_option, id, {
            type = "toggle",
            label = p.zh,
            mod = "军械工坊",
            description = desc and table.concat(desc, " / ") or nil,
            default = chosen[p.id] == true,
        })
        if called and done == true then
            made = made + 1
        else
            failed = failed + 1
            if failed <= 3 then log("OPTIONS register " .. id .. " failed: " .. tostring(why or done)) end
        end
        pcall(options_api.on_change, id, function(value) options_apply(id, value) end)
    end
    local called, done = pcall(options_api.register_option, "armory_keep_original", {
        type = "toggle",
        label = "保留护甲自带被动",
        mod = "军械工坊",
        description = "关掉后不再叠加护甲原本的那条被动。",
        default = keep_original == true,
    })
    if called and done == true then made = made + 1 else failed = failed + 1 end
    pcall(options_api.on_change, "armory_keep_original",
        function(value) options_apply("armory_keep_original", value) end)
    -- 玩家可能在上次游戏里就在设置页改过：以设置页存下来的值为准采纳进草稿，
    -- 再排一次队，这样「设置页改了、下次进游戏就按新的来」也成立。
    local adopted = 0
    for _, p in ipairs(PASSIVES) do
        local id = "armory_passive_" .. p.id
        local ok, value = pcall(options_api.get, id)
        if ok and type(value) == "boolean" and (value == true) ~= (chosen[p.id] == true) then
            if value then chosen[p.id] = true else chosen[p.id] = nil end
            adopted = adopted + 1
        end
    end
    local ok_keep, keep_value = pcall(options_api.get, "armory_keep_original")
    if ok_keep and type(keep_value) == "boolean" and keep_value ~= (keep_original == true) then
        keep_original = keep_value
        write(keep_path, keep_value and "1" or "0")
        adopted = adopted + 1
    end
    if adopted > 0 then
        options_stage_pending = true
        log("OPTIONS adopted " .. adopted .. " value(s) from the options page")
    end
    options_sync()
    log(string.format("OPTIONS ready v%s: %d registered, %d failed", MOD_VERSION, made, failed))
end

-- 注册放在 initialize 之后：此时草稿已从 pending/.state 读回，默认值才是对的。
-- on_enable 也会调一次，用标志位挡住重复注册。
local options_registered = false
local function options_enable()
    if not options_ready then return end
    if options_registered then options_sync(); return end
    options_registered = true
    local ok, why = pcall(options_register)
    if not ok then log("OPTIONS ERROR " .. tostring(why)) end
end
options_enable()

-- 返回表（MDL3 的 on_enable/on_update/on_disable）与 _G 链二选一生效：
-- driven_by_table 为真说明宿主在按表驱动，_G 那边就只转发上一个 update。
local previous_update = rawget(_G, "update")
local previous_shutdown = rawget(_G, "shutdown")
local update_error_logged = false
local driven_by_table = false
local finish_done = false
local function table_update()
    driven_by_table = true
    safe_update()
end
local function table_shutdown()
    if finish_done then return end
    finish_done = true
    local ok, why = pcall(finish, "exit")
    if not ok then pcall(log, "SHUTDOWN ERROR " .. tostring(why)) end
end
rawset(_G, "update", function(...)
    if type(previous_update) == "function" then
        local ok, why = pcall(previous_update, ...)
        if not ok and not update_error_logged then
            update_error_logged = true
            pcall(log, "PREVIOUS UPDATE ERROR " .. tostring(why))
        end
    end
    if not driven_by_table then safe_update() end
    -- 模组设置页攒下的改动合并成一次排队；面板里的改动推回设置页。
    if options_stage_pending then
        options_stage_pending = false
        options_stage()
    end
    if options_push_all then
        options_push_all = false
        options_sync()
    end
end)
rawset(_G, "shutdown", function(...)
    table_shutdown()
    if type(previous_shutdown) == "function" then return previous_shutdown(...) end
end)
log("chain installed (update/shutdown wrapped)")
-- 交底行：装的是哪版、跑在谁下面、键来自文件还是默认、字体打算走哪条路。
-- 字体最终结果看 setup_font() 打的 "FONT native ready" / "FONT unavailable"。
log(string.format("ARMORY-FORGE v%s | host=%s | keys=%s | bind_api=%s | font=%s",
    MOD_VERSION, host_kind(),
    tostring(read(keys_path) and "file" or "default"),
    tostring(rawget(_G, "ModBindingsMenu") and "yes" or "no"),
    tostring(font_dead and "pixel(dead)" or "auto")))

-- MDL3 按这个表驱动（on_enable / on_update / on_disable）；
-- 只认 update/shutdown 的旧宿主用下面同名的几个字段，两套都挂上也不会跑两遍。
return {
    name = "军械工坊",
    version = MOD_VERSION,
    on_enable = options_enable,
    on_update = table_update,
    on_disable = function()
        pcall(close_menu)
        gui, gui_world, highlight = nil, nil, nil
        log("DISABLED")
    end,
    init = noop,
    update = table_update,
    render = noop,
    shutdown = table_shutdown,
}
